const $ = id => document.getElementById(id);
const stored = (key, fallback) => { try { return localStorage.getItem('lectoria_'+key) ?? fallback; } catch { return fallback; } };
const store = (key,value) => { try { localStorage.setItem('lectoria_'+key,String(value)); } catch {} };
const state = { user:null, docs:[], doc:null, section:0, chunks:[], index:0, offset:0, position:0, status:'idle', generation:0, controller:null, url:null, blob:null, cache:new Map(), page:1, selection:null, font:Number(stored('font',20)), bookRequest:0, blogPage:1, postRequest:0, jobs:[], speeds:{}, cloud:false, jobTimer:null, voices:[], queue:[], playlists:[], playlist:null, action:null };
const audio = $('audio'); let toastTimer, progressTimer;
async function api(route, options={}) {
  const response = await fetch('./api/'+route,{...options,headers:{...(options.body && !(options.body instanceof Blob)?{'Content-Type':'application/json'}:{}),...options.headers}});
  if(!response.ok){const data=await response.json().catch(()=>({}));const e=new Error(data.error || 'Não foi possível concluir o pedido.');e.status=response.status;if(response.status===401 && state.user){state.user=null;updateAccount();}throw e;}
  return response.headers.get('content-type')?.includes('audio/')?response.blob():response.json();
}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6000);}
