function applyAppearance(){document.documentElement.dataset.theme=stored('theme',matchMedia('(prefers-color-scheme: light)').matches?'light':'dark');const mode=stored('mode','standard');document.body.classList.toggle('mode-clean',mode==='clean');document.body.classList.toggle('mode-reading',mode==='reading');$('clean-mode').setAttribute('aria-pressed',mode==='clean');$('reading-mode').setAttribute('aria-pressed',mode==='reading');$('theme-toggle').textContent=document.documentElement.dataset.theme==='dark'?'☾':'☀';$('theme-toggle').setAttribute('aria-label',document.documentElement.dataset.theme==='dark'?'Ativar tema claro':'Ativar tema escuro');document.documentElement.style.setProperty('--reading-font',Math.min(30,Math.max(16,state.font))+'px');}
