$('login-form').onsubmit=async event=>{event.preventDefault();$('login-error').textContent='';const button=event.currentTarget.querySelector('button[type=submit]');button.disabled=true;try{const apiKey=$('api-key').value.trim();state.user=await api('login',{method:'POST',body:JSON.stringify(apiKey?{apiKey}:{username:$('username').value.trim(),password:$('password').value})});$('password').value='';$('api-key').value='';$('login-dialog').close();updateAccount();await Promise.all([refreshShelf(),loadVoices(),loadLibraries(),loadLists()]);if(!$('audio-view').hidden)refreshJobs();if(!$('blog-select').value)loadBlogs();renderQueue();renderPlaylists();updateUpNext();toast('Bem-vindo, '+state.user.username+'.');}catch(e){$('login-error').textContent=e.message;}finally{button.disabled=false;}};
async function refreshShelf(){if(!state.user){state.docs=[];renderDocuments();return;}try{state.docs=await api('documents');renderDocuments();}catch(e){toast(e.message);}}
function documentCard(doc, kind='shelf'){const card=document.createElement('div');card.className='document-card';const button=document.createElement('button');button.className='document-open';const cover=document.createElement('div');cover.className='document-cover';const small=document.createElement('small');small.textContent=kind==='kavita'?'KAVITA':kind==='blog'?'BLOGUE':doc.source||'DOCUMENTO';const title=document.createElement('span');title.textContent=String(doc.title||doc.name||'Sem título');title.className='cover-title';const symbol=document.createElement('span');symbol.className='cover-symbol';symbol.textContent=kind==='blog'?'✦':'▤';if(kind==='kavita'){const image=document.createElement('img');image.className='cover-image';image.loading='lazy';image.alt='';image.src='./api/cover?series='+encodeURIComponent(doc.id);image.onerror=()=>image.remove();cover.append(image);}cover.append(small,title,symbol);const body=document.createElement('div');body.className='document-body';button.title=doc.title||doc.name||'';const caption=document.createElement('p');caption.textContent=kind==='kavita'?'Escolher livro e ouvir →':kind==='blog'?`${doc.published.slice(0,10)} · ${Math.max(1,Math.round(doc.chars/1000))} mil caracteres · Ler e ouvir →`:`${doc.sections} ${doc.sections===1?'secção':'secções'} · Ler e ouvir →`;body.append(caption);button.append(cover,body);button.onclick=()=>kind==='kavita'?chooseBook(doc):kind==='blog'?importPost(doc):openSaved(doc.id);card.append(button);const menu=document.createElement('button');menu.className='card-menu';menu.textContent='⋯';menu.setAttribute('aria-label','Opções de '+(doc.title||doc.name));menu.onclick=e=>{e.stopPropagation();itemMenu(doc,kind);};card.append(menu);if(kind==='shelf'){const remove=document.createElement('button');remove.className='document-delete';remove.textContent='Remover';remove.setAttribute('aria-label','Remover '+doc.title);remove.onclick=async()=>{if(!confirm('Remover este documento da tua estante?'))return;try{await api('documents/'+doc.id,{method:'DELETE'});if(state.doc?.id===doc.id){stop();state.doc=null;$('player').hidden=true;changeView('shelf');}await refreshShelf();}catch(e){toast(e.message);}};card.append(remove);}return card;}
function empty(target,message){const item=document.createElement('div');item.className='empty-state';item.textContent=message;target.append(item);}
function renderDocuments(){for(const[id,limit]of[['recent-documents',4],['shelf-documents',80]]){const target=$(id);target.replaceChildren();state.docs.slice(0,limit).forEach(d=>target.append(documentCard(d)));if(!state.docs.length)empty(target,state.user?'A tua estante está pronta para a primeira leitura.':'Entra no Kavita para guardar documentos e continuar as tuas leituras.');}}
async function loadLibraries(){try{const libraries=await api('libraries');$('library-select').replaceChildren();for(const lib of libraries){const option=document.createElement('option');option.value=lib.id;option.textContent=lib.name;$('library-select').append(option);}if(!libraries.length){empty($('book-grid'),'Não há bibliotecas disponíveis nesta conta.');return;}state.page=1;await loadBooks();}catch(e){toast(e.message);}}
async function loadBooks(){if(!requireUser()||!$('library-select').value)return;const generation=++state.bookRequest;const target=$('book-grid');target.replaceChildren();empty(target,'A procurar na tua biblioteca…');try{const data=await api(`books?library=${encodeURIComponent($('library-select').value)}&page=${state.page}&q=${encodeURIComponent($('book-search').value)}`);if(generation!==state.bookRequest)return;target.replaceChildren();for(const book of data.books)target.append(documentCard(book,'kavita'));if(!data.books.length)empty(target,'Não foram encontrados livros.');$('page-label').textContent='Página '+state.page;$('previous-page').disabled=state.page===1;$('next-page').disabled=data.books.length<48;}catch(e){if(generation!==state.bookRequest)return;target.replaceChildren();empty(target,e.message);}}
$('library-select').onchange=()=>{state.page=1;loadBooks();};$('search-books').onclick=()=>{state.page=1;loadBooks();};$('book-search').onkeydown=e=>{if(e.key==='Enter')$('search-books').click();};$('previous-page').onclick=()=>{if(state.page>1){state.page--;loadBooks();}};$('next-page').onclick=()=>{state.page++;loadBooks();};
function blogPlaceholder(text){const option=document.createElement('option');option.value='';option.textContent=text;$('blog-select').replaceChildren(option);}
async function loadBlogs(){if(!state.user){blogPlaceholder('Entra no Kavita para ver os blogues');$('post-grid').replaceChildren();empty($('post-grid'),'Os blogues ficam disponíveis depois de entrares.');login();return;}blogPlaceholder('A carregar blogues…');try{const blogs=await api('blogs');$('blog-select').replaceChildren();for(const blog of blogs){const option=document.createElement('option');option.value=blog.index;option.textContent=blog.title;$('blog-select').append(option);}if(!blogs.length){empty($('post-grid'),'Não há blogues configurados neste servidor.');return;}state.blogPage=1;await loadPosts();}catch(e){blogPlaceholder(e.status===401?'Entra no Kavita para ver os blogues':'Sem ligação aos blogues');$('post-grid').replaceChildren();empty($('post-grid'),e.message);if(e.status===401)login();}}
async function loadPosts(){if($('blog-select').value==='')return;const generation=++state.postRequest;const target=$('post-grid');target.replaceChildren();empty(target,'A procurar artigos…');try{const data=await api(`blog-posts?blog=${encodeURIComponent($('blog-select').value)}&page=${state.blogPage}`);if(generation!==state.postRequest)return;target.replaceChildren();for(const post of data.posts)target.append(documentCard(post,'blog'));if(!data.posts.length)empty(target,'Este blogue ainda não tem artigos publicados.');$('posts-label').textContent='Página '+state.blogPage+' · '+data.total+' artigos';$('previous-posts').disabled=state.blogPage===1;$('next-posts').disabled=state.blogPage*24>=data.total;}catch(e){if(generation!==state.postRequest)return;target.replaceChildren();empty(target,e.message);}}
$('blog-select').onchange=()=>{state.blogPage=1;loadPosts();};$('previous-posts').onclick=()=>{if(state.blogPage>1){state.blogPage--;loadPosts();}};$('next-posts').onclick=()=>{state.blogPage++;loadPosts();};
async function importPost(post,action=null){if(!requireUser())return;if(!action)stop();await busy('A preparar o artigo…',async()=>{const doc=await api('import-post',{method:'POST',body:JSON.stringify({blog:Number($('blog-select').value),post:post.id})});await refreshShelf();if(action)await runAction(action,doc);else await openDoc(doc);});}
async function chooseBook(book){await busy('A abrir os livros desta série…',async()=>{const chapters=await api('chapters?series='+book.id);$('book-title').textContent=book.name;$('book-chapters').replaceChildren();if(!chapters.length)empty($('book-chapters'),'Esta série não tem livros disponíveis.');for(const chapter of chapters){const button=document.createElement('button');button.className='chapter-choice';button.textContent=(chapter.title==='Livro'?book.name:chapter.title)+' · '+chapter.pages+' páginas';button.onclick=()=>importBook(chapter,book,state.action);$('book-chapters').append(button);}$('chapters-dialog').showModal();});}
async function importBook(chapter,book,action=null){$('chapters-dialog').close();state.action=null;if(!action)stop();await busy('A preparar o texto do livro…',async()=>{const doc=await api('import-book',{method:'POST',body:JSON.stringify({chapter:chapter.id,title:chapter.title==='Livro'?book.name:chapter.title})});await refreshShelf();if(action)await runAction(action,doc);else await openDoc(doc);});}
function uploadFile(file){if(!file||!requireUser())return;if(file.size>50*1024*1024)return toast('O limite por documento é 50 MB.');stop();busy('A abrir '+file.name+'…',async()=>{const doc=await api('upload?name='+encodeURIComponent(file.name),{method:'POST',body:file,headers:{'Content-Type':'application/octet-stream'}});await refreshShelf();await openDoc(doc);});}
$('file-input').onchange=event=>{uploadFile(event.target.files[0]);event.target.value='';};$('drop-zone').onclick=$('upload-shelf').onclick=()=>{if(requireUser())$('file-input').click();};$('drop-zone').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('drop-zone').click();}};for(const event of ['dragenter','dragover'])$('drop-zone').addEventListener(event,e=>{e.preventDefault();$('drop-zone').classList.add('dragging');});for(const event of ['dragleave','drop'])$('drop-zone').addEventListener(event,e=>{e.preventDefault();$('drop-zone').classList.remove('dragging');if(event==='drop')uploadFile(e.dataTransfer.files[0]);});window.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault();});window.addEventListener('drop',e=>{if(e.dataTransfer.files.length){e.preventDefault();if(!e.target.closest('#drop-zone'))uploadFile(e.dataTransfer.files[0]);}});
$('text-input').value=stored('draft','');$('text-title').value=stored('draft-title','');function countText(){$('character-count').textContent=$('text-input').value.length.toLocaleString('pt-PT')+' caracteres';store('draft',$('text-input').value);store('draft-title',$('text-title').value);}$('text-input').oninput=$('text-title').oninput=countText;countText();
$('text-form').onsubmit=event=>{event.preventDefault();if(!requireUser())return;busy('A guardar as tuas palavras…',async()=>{const doc=await api('documents',{method:'POST',body:JSON.stringify({title:$('text-title').value.trim()||'As minhas palavras',source:'Texto escrito',sections:[{title:'Texto',text:$('text-input').value}]})});await refreshShelf();await openDoc(doc);});};
async function openSaved(id){await busy('A abrir a tua leitura…',async()=>openDoc(await api('documents/'+id)));}
async function openDoc(doc){saveProgress(true);stop();state.doc=doc;let progress={section:0,position:0};try{progress=await api('documents/'+doc.id+'/progress');}catch{}state.section=Math.min(progress.section||0,doc.sections.length-1);renderChapters();renderSection(progress.position||0);$('reader-title').textContent=$('reader-title-side').textContent=doc.title;$('reader-source').textContent=doc.source;$('now-playing').textContent=doc.title;$('player').hidden=false;changeView('reader');if(!$('voice').options[0]?.value)await loadVoices();applyPreferredVoice(doc);setStatus('idle');if(progress.position)requestAnimationFrame(()=>document.querySelector('#reader-text p.active')?.scrollIntoView({block:'center'}));}
function renderChapters(){const target=$('chapter-list');target.replaceChildren();state.doc.sections.forEach((section,index)=>{const button=document.createElement('button');button.textContent=String(index+1).padStart(2,'0')+' · '+section.title;button.className=index===state.section?'active':'';button.onclick=()=>changeSection(index);target.append(button);});}
function totalChars(){return state.chunks.reduce((sum,c)=>sum+c.length,0)||1;}
function startChars(index){return state.chunks.slice(0,index).reduce((sum,c)=>sum+c.length,0);}
function locate(position){let remaining=position;for(let i=0;i<state.chunks.length;i++){if(remaining<state.chunks[i].length)return {index:i,offset:remaining};remaining-=state.chunks[i].length;}return {index:Math.max(0,state.chunks.length-1),offset:0};}
function renderSection(position=0){const section=state.doc.sections[state.section];state.chunks=chunks(section.text);state.position=Math.min(position,totalChars()-1);Object.assign(state,locate(state.position));$('section-title').textContent=section.title;$('section-label').textContent='SECÇÃO '+String(state.section+1).padStart(2,'0');$('section-count').textContent=(state.section+1)+'/'+state.doc.sections.length;const target=$('reader-text');target.replaceChildren();state.chunks.forEach((text,index)=>{const p=document.createElement('p');p.textContent=text;p.dataset.index=index;p.tabIndex=0;p.onclick=()=>{if(!window.getSelection()?.isCollapsed)return;seek(index,0);};p.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();seek(index,0);}};target.append(p);});$('previous-chapter').disabled=state.section===0;$('next-chapter').disabled=state.section===state.doc.sections.length-1;state.selection=null;$('selection-play').hidden=true;updateProgress();highlight();}
function changeSection(index,autoplay=false){if(!state.doc||index<0||index>=state.doc.sections.length)return;saveProgress(true);stop();state.section=index;state.cache.clear();renderChapters();renderSection();saveProgress();if(autoplay)seek(0,0);else window.scrollTo({top:0,behavior:'instant'});}
$('previous-chapter').onclick=()=>changeSection(state.section-1);$('next-chapter').onclick=()=>changeSection(state.section+1);
for(const [id,delta]of[['font-smaller',-1],['font-larger',1]])$(id).onclick=()=>{state.font=Math.min(30,Math.max(16,state.font+delta));store('font',state.font);applyAppearance();};
function captureSelection(){const selection=window.getSelection();if(!selection||selection.isCollapsed){$('selection-play').hidden=true;return;}const range=selection.getRangeAt(0);const node=range.startContainer.nodeType===Node.ELEMENT_NODE?range.startContainer:range.startContainer.parentElement;const paragraph=node.closest('p[data-index]');if(!paragraph||!$('reader-text').contains(paragraph))return;const before=document.createRange();before.setStart(paragraph,0);before.setEnd(range.startContainer,range.startOffset);state.selection={index:Number(paragraph.dataset.index),offset:before.toString().length};$('selection-play').hidden=false;}
$('reader-text').addEventListener('mouseup',captureSelection);$('reader-text').addEventListener('keyup',captureSelection);$('reader-text').addEventListener('touchend',()=>setTimeout(captureSelection,100));$('selection-play').onclick=()=>{if(state.selection)seek(state.selection.index,state.selection.offset);window.getSelection()?.removeAllRanges();$('selection-play').hidden=true;};
