// Phones suspend a page that is not playing anything: between passages (while the next one is generated) the
// reading would die. A 40 Hz sine at -60 dBFS (33 LSB, two-second loop) keeps the page counted as playing without being heard.
let keepAlive;function keepAliveAudio(on){if(!matchMedia('(pointer:coarse)').matches)return;if(!keepAlive){const rate=44100,samples=rate*2;const buffer=new ArrayBuffer(44+samples*2);const view=new DataView(buffer);const str=(o,t)=>{for(let i=0;i<t.length;i++)view.setUint8(o+i,t.charCodeAt(i));};str(0,'RIFF');view.setUint32(4,36+samples*2,true);str(8,'WAVEfmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,1,true);view.setUint32(24,rate,true);view.setUint32(28,rate*2,true);view.setUint16(32,2,true);view.setUint16(34,16,true);str(36,'data');view.setUint32(40,samples*2,true);for(let i=0;i<samples;i++)view.setInt16(44+i*2,Math.round(Math.sin(2*Math.PI*40*i/rate)*33),true);keepAlive=new Audio(URL.createObjectURL(new Blob([buffer],{type:'audio/wav'})));keepAlive.loop=true;}if(on){if(keepAlive.paused)keepAlive.play().catch(()=>{});}else keepAlive.pause();}
function setStatus(status){state.status=status;keepAliveAudio(status==='playing'||status==='loading');if('mediaSession'in navigator)navigator.mediaSession.playbackState=status==='playing'||status==='loading'?'playing':status==='paused'?'paused':'none';$('play').textContent=status==='playing'?'Ⅱ':'▶';$('play').setAttribute('aria-label',status==='playing'?'Pausar':status==='paused'?'Retomar':'Ouvir');$('player-state').textContent=({idle:'Pronto para ouvir',loading:'A preparar a próxima passagem…',playing:'A ouvir · '+(state.index+1)+'/'+state.chunks.length,paused:'Em pausa',finished:'Leitura concluída'})[status];$('play').disabled=status==='loading';}
function stop(){state.generation++;state.controller?.abort();state.controller=null;audio.pause();audio.removeAttribute('src');audio.load();if(state.url)URL.revokeObjectURL(state.url);state.url=null;state.blob=null;setStatus('idle');}
function updateProgress(){const ratio=Math.min(1,state.position/totalChars());$('position').value=Math.round(ratio*1000);$('progress-label').textContent=Math.round(ratio*100)+'%';}
function saveProgress(immediate=false){clearTimeout(progressTimer);if(!state.user||!state.doc?.id)return;const id=state.doc.id,section=state.section,position=Math.max(0,Math.floor(state.position));const save=()=>api('documents/'+id+'/progress',{method:'PUT',body:JSON.stringify({section,position})}).catch(()=>{});if(immediate)save();else progressTimer=setTimeout(save,1200);}
// Cheap language guess from common words; null when the text does not lean clearly either way.
function detectLanguage(text){const sample=' '+text.slice(0,4000).toLowerCase().replace(/[^\p{L}\s]/gu,' ')+' ';const count=words=>words.reduce((n,w)=>n+sample.split(' '+w+' ').length-1,0);const pt=count(['de','que','não','uma','para','com','os','do','da','é','em','mais','por','como','mas','isso','são','também','ao','dos','das','já','ele','ela','seu','sua','foi','muito','até','onde']);const en=count(['the','and','of','to','in','is','that','it','for','was','with','as','on','be','at','by','this','have','from','or','are','not','but','they','his','her','which','you','were','there']);return en>pt*1.2?'en-US':pt>en*1.2?'pt-PT':null;}
const voiceLang=id=>state.voices.find(v=>v.id===id)?.lang;
