function applyPreferredVoice(doc){if(stored('autoLang','1')!=='1'||!state.voices.length)return;const lang=detectLanguage(doc.sections.map(s=>s.text).join('\n'));const voice=lang&&preferredVoice(lang);if(voice&&voice!==$('voice').value){$('voice').value=voice;store('voice',voice);state.cache.clear();engineHint();}}
function renderSettings(){for(const lang of ['pt-PT','en-US']){const select=$('pref-'+lang);select.replaceChildren();for(const voice of state.voices.filter(v=>v.lang===lang)){const option=document.createElement('option');option.value=voice.id;option.textContent=voice.name;select.append(option);}if(!select.children.length){const option=document.createElement('option');option.value='';option.textContent=state.user?'Sem vozes disponíveis':'Entra no Kavita para ver as vozes';select.append(option);}else select.value=preferredVoice(lang);}$('auto-language').checked=stored('autoLang','1')==='1';$('pref-engine').value=stored('engine','host');$('cache-behind').value=cacheSetting('cacheBehind');$('cache-ahead').value=cacheSetting('cacheAhead');$('prefetch-mode').value=stored('prefetchMode','window');cacheEstimate();}
$('prefetch-mode').onchange=()=>{store('prefetchMode',$('prefetch-mode').value);cacheEstimate();if(state.status==='playing')prefetch(state.index,state.generation);};
for(const lang of ['pt-PT','en-US'])$('pref-'+lang).onchange=()=>{store('voice_'+lang,$('pref-'+lang).value);if(state.doc&&voiceLang($('voice').value)===lang){$('voice').value=$('pref-'+lang).value;$('voice').onchange();}};
