// Engine placement: host (default), this device, or both alternating passages. Only voices with a browser model can leave the host.
let localWorker,localSeq=0;const localJobs=new Map();
const localVoice=id=>id==='pt_PT-tugao'||/^a[fm]_/.test(id);
function engineFor(index){const mode=stored('engine','host');if(mode==='host'||!localVoice($('voice').value))return 'host';return mode==='local'||index%2?'local':'host';}
function localSynth(text,voice,rate){if(!localWorker){localWorker=new Worker('./local-worker.js',{type:'module'});localWorker.onmessage=({data})=>{const job=localJobs.get(data.id);if(!job)return;if(data.progress){if(state.status==='loading')$('player-state').textContent=data.progress.phase==='download'?'A descarregar a voz para este dispositivo… '+Math.round(data.progress.ratio*100)+'%':'A gerar neste dispositivo…';return;}localJobs.delete(data.id);if(data.error)job.reject(new Error('A voz neste dispositivo falhou ('+data.error.slice(0,80)+').'));else job.resolve({blob:new Blob([data.wav],{type:'audio/wav'}),rate:data.playbackRate});};localWorker.onerror=()=>{for(const job of localJobs.values())job.reject(new Error('Não foi possível carregar a voz neste dispositivo.'));localJobs.clear();localWorker.terminate();localWorker=null;};}const id=++localSeq;return new Promise((resolve,reject)=>{localJobs.set(id,{resolve,reject});localWorker.postMessage({id,text,voice,rate});});}
const cacheSetting=key=>Math.max(key==='cacheAhead'?1:0,Math.min(20,Number(stored(key,3))||0));
function pruneCache(){const behind=cacheSetting('cacheBehind'),ahead=stored('prefetchMode','window')==='section'?Infinity:cacheSetting('cacheAhead');for(const key of [...state.cache.keys()]){const [docId,section,index]=key.split(':');if(docId!==String(state.doc?.id)||Number(section)!==state.section||Number(index)<state.index-behind||Number(index)>state.index+ahead)state.cache.delete(key);}markReady();}
function cacheBytes(){let bytes=0;for(const entry of state.cache.values())bytes+=entry.blob?.size||0;return bytes;}
function markReady(){if(!state.doc)return;const ready=new Set();for(const key of state.cache.keys()){const [docId,section,index,offset]=key.split(':');if(docId===String(state.doc.id)&&Number(section)===state.section&&offset==='0')ready.add(Number(index));}document.querySelectorAll('#reader-text p').forEach((p,i)=>p.classList.toggle('ready',ready.has(i)));const total=totalChars();$('buffered').replaceChildren(...[...ready].map(i=>{const span=document.createElement('span');span.style.left=startChars(i)/total*100+'%';span.style.width=state.chunks[i].length/total*100+'%';if(i===state.index)span.className='active';return span;}));if(!$('settings-view').hidden)cacheEstimate();}
function cacheEstimate(){const section=stored('prefetchMode','window')==='section';const slots=section&&state.doc?Math.max(state.chunks.length,cacheSetting('cacheBehind')+1):cacheSetting('cacheBehind')+cacheSetting('cacheAhead')+1;$('cache-ahead').disabled=section;const mb=n=>(n/1048576).toLocaleString('pt-PT',{maximumFractionDigits:1})+' MB';$('cache-estimate').textContent=`Até ${slots} passagens em memória · cerca de ${mb(slots*800000)} (áudio sem compressão, ~0,8 MB por passagem) · agora: ${mb(cacheBytes())} em ${state.cache.size} passagens.`;}
for(const key of ['cache-behind','cache-ahead'])$(key).onchange=()=>{store(key==='cache-behind'?'cacheBehind':'cacheAhead',$(key).value);$(key).value=cacheSetting(key==='cache-behind'?'cacheBehind':'cacheAhead');pruneCache();cacheEstimate();};
function cacheKey(index,offset){return [state.doc.id,state.section,index,offset,$('voice').value,$('speed').value].join(':');}
function sleep(ms,signal){return new Promise((resolve,reject)=>{if(signal.aborted)return reject(new DOMException('Aborted','AbortError'));const abort=()=>{clearTimeout(timer);reject(new DOMException('Aborted','AbortError'));};const timer=setTimeout(()=>{signal.removeEventListener('abort',abort);resolve();},ms);signal.addEventListener('abort',abort,{once:true});});}
async function hostSynth(text,signal){for(let attempt=0;;attempt++){try{return {blob:await api('voice',{method:'POST',signal,body:JSON.stringify({text,voice:$('voice').value,rate:Number($('speed').value)})}),rate:1};}catch(e){if(e.status!==429||attempt===29)throw e;await sleep(2000,signal);}}}
async function synth(index,offset,signal,engine=engineFor(index)){const key=cacheKey(index,offset);if(state.cache.has(key))return state.cache.get(key);const text=state.chunks[index].slice(offset);let entry;if(engine==='local'){try{entry=await localSynth(text,$('voice').value,Number($('speed').value));}catch(e){toast(e.message+' A usar o servidor.');entry=await hostSynth(text,signal);}}else entry=await hostSynth(text,signal);if(signal.aborted)throw new DOMException('Aborted','AbortError');state.cache.set(key,entry);pruneCache();return entry;}
async function playPassage(index,offset,generation){if(!state.chunks[index])return;state.index=index;state.offset=Math.min(offset,state.chunks[index].length-1);state.position=startChars(index)+state.offset;highlight();updateProgress();saveProgress();setStatus('loading');try{const entry=await synth(index,state.offset,state.controller.signal);if(generation!==state.generation)return;if(state.url)URL.revokeObjectURL(state.url);state.blob=entry.blob;state.url=URL.createObjectURL(entry.blob);audio.src=state.url;audio.playbackRate=entry.rate;audio.volume=Number($('volume').value)/100;audio.onended=()=>{if(generation!==state.generation)return;if(index+1<state.chunks.length)playPassage(index+1,0,generation);else if(state.section+1<state.doc.sections.length)changeSection(state.section+1,true);else{state.position=totalChars();updateProgress();saveProgress(true);setStatus('finished');playNextInQueue();}};try{await audio.play();if(generation===state.generation)setStatus('playing');}catch{if(generation===state.generation){setStatus('paused');toast('Toca em play para começar a ouvir.');}}prefetch(index,generation);if('mediaSession'in navigator){navigator.mediaSession.metadata=new MediaMetadata({title:state.doc.title,artist:'Lectoria · '+$('voice').selectedOptions[0].textContent,album:state.doc.sections[state.section].title});}}catch(e){if(generation!==state.generation)return;setStatus('paused');toast(e.message);}}
// The engine serves one passage at a time, so the next three are requested one after another while this one plays.
// The engine serves one passage at a time, so the next passages are requested one after another while this one plays; with two engines each gets its own chain.
function prefetch(index,generation){const chains={host:Promise.resolve(),local:Promise.resolve()};for(let ahead=1;ahead<=(stored('prefetchMode','window')==='section'?state.chunks.length:cacheSetting('cacheAhead'));ahead++){const next=index+ahead;if(!state.chunks[next])break;const engine=engineFor(next);chains[engine]=chains[engine].then(()=>{if(generation===state.generation)return synth(next,0,state.controller.signal,engine);}).catch(()=>{});}}
function seek(index,offset=0){if(!requireUser()||!state.doc)return;if(!$('voice').value){toast('Não há vozes disponíveis.');return;}stop();state.controller=new AbortController();playPassage(index,offset,state.generation);}
$('play').onclick=()=>{if(!state.doc)return;if(state.status==='playing'){audio.pause();setStatus('paused');saveProgress();}else if(state.status==='paused'&&state.url){audio.play().then(()=>setStatus('playing')).catch(()=>toast('Não foi possível retomar o áudio.'));}else{const pos=state.position>=totalChars()?{index:0,offset:0}:locate(state.position);seek(pos.index,pos.offset);}};$('stop').onclick=()=>{saveProgress(true);stop();};
$('position').onchange=()=>{const pos=locate(Math.floor(Number($('position').value)/1000*(totalChars()-1)));if(pos.index===state.index&&pos.offset>=state.offset&&state.url&&Number.isFinite(audio.duration)){audio.currentTime=(pos.offset-state.offset)/(state.chunks[pos.index].length-state.offset)*audio.duration;state.position=startChars(pos.index)+pos.offset;updateProgress();saveProgress();}else seek(pos.index,pos.offset);};
function skip(seconds){if(Number.isFinite(audio.duration)&&audio.src){const target=audio.currentTime+seconds;if(target>=audio.duration){if(state.index+1<state.chunks.length)seek(state.index+1);else if(state.section+1<state.doc.sections.length)changeSection(state.section+1,true);else audio.currentTime=audio.duration;}else if(target<0&&state.index>0)seek(state.index-1);else audio.currentTime=Math.max(0,target);}else{seek(Math.max(0,Math.min(state.chunks.length-1,state.index+(seconds>0?1:-1))));}}
$('rewind').onclick=()=>skip(-10);$('forward').onclick=()=>skip(10);
audio.ontimeupdate=()=>{if(!state.doc||!Number.isFinite(audio.duration)||!audio.duration)return;state.position=startChars(state.index)+state.offset+(state.chunks[state.index].length-state.offset)*(audio.currentTime/audio.duration);updateProgress();saveProgress();};
// Own vertical slider: native vertical ranges are not reliable across phone browsers.
function setVolume(value,save=true){value=Math.max(0,Math.min(100,Math.round(Number(value))));$('volume').value=value;audio.volume=value/100;if(save)store('volume',value);$('volume-button').dataset.level=value===0?'0':value<50?'1':'2';$('volume-slider').setAttribute('aria-valuenow',value);$('volume-slider').querySelector('.volume-fill').style.height=value+'%';$('volume-slider').querySelector('.volume-thumb').style.bottom=value+'%';}
setVolume(stored('volume','80'),false);$('volume').oninput=()=>setVolume($('volume').value);
{const slider=$('volume-slider');const fromEvent=e=>{const rect=slider.getBoundingClientRect();return (1-(e.clientY-rect.top)/rect.height)*100;};slider.onpointerdown=e=>{slider.setPointerCapture(e.pointerId);setVolume(fromEvent(e));slider.onpointermove=ev=>setVolume(fromEvent(ev));};slider.onpointerup=slider.onpointercancel=()=>{slider.onpointermove=null;};slider.onkeydown=e=>{const step={ArrowUp:5,ArrowRight:5,ArrowDown:-5,ArrowLeft:-5}[e.key];if(step!==undefined){e.preventDefault();setVolume(Number($('volume').value)+step);}};}$('volume-button').onclick=()=>{const open=$('volume-panel').hidden;$('volume-panel').hidden=!open;$('volume-button').setAttribute('aria-expanded',String(open));};document.addEventListener('pointerdown',e=>{if(!$('volume-panel').hidden&&!e.target.closest('.volume-pop')){$('volume-panel').hidden=true;$('volume-button').setAttribute('aria-expanded','false');}});$('speed').value=stored('speed','1');$('speed').onchange=()=>{store('speed',$('speed').value);state.cache.clear();if(state.doc)seek(state.index,state.offset);};$('voice').onchange=()=>{store('voice',$('voice').value);const lang=voiceLang($('voice').value);if(lang)store('voice_'+lang,$('voice').value);state.cache.clear();engineHint();if(state.doc)seek(state.index,state.offset);};
function engineHint(){const mode=$('engine').value;$('engine').title=mode==='host'?'As vozes são geradas no servidor.':localVoice($('voice').value)?'Só o Tugão e as vozes Kokoro em inglês têm modelo para o browser (descarregado uma vez, 60 a 90 MB).':'Esta voz não tem modelo para o browser: é gerada no servidor.';}
$('engine').value=stored('engine','host');engineHint();$('engine').onchange=()=>{store('engine',$('engine').value);engineHint();if(stored('engine')!=='host'&&!localVoice($('voice').value))toast('Esta voz só existe no servidor. Escolhe o Tugão ou uma voz Kokoro para usar este dispositivo.');};
async function loadVoices(){try{const data=await api('voices');state.voices=data.voices;const previous=stored('voice','pt_PT-tugao');$('voice').replaceChildren();const langs=[['pt-PT','Português · Portugal'],['en-US','English · USA']];for(const[lang,title]of langs){const group=document.createElement('optgroup');group.label=title;for(const voice of data.voices.filter(v=>v.lang===lang)){const option=document.createElement('option');option.value=voice.id;option.textContent=voice.name;group.append(option);}if(group.children.length)$('voice').append(group);}if([...$('voice').options].some(o=>o.value===previous))$('voice').value=previous;if(!data.voices.length){const o=document.createElement('option');o.value='';o.textContent='Vozes indisponíveis';$('voice').append(o);}}catch(e){toast(e.message);}}
