function docInfo(id){return state.docs.find(d=>d.id===id);}
async function saveQueue(){try{await api('queue',{method:'PUT',body:JSON.stringify({items:state.queue})});}catch(e){toast(e.message);}if(!$('queue-view').hidden)renderQueue();updateUpNext();}
async function loadLists(){if(!state.user){state.queue=[];state.playlists=[];return;}try{const [queue,playlists]=await Promise.all([api('queue'),api('playlists')]);state.queue=queue.items;state.playlists=playlists;}catch{}}
function itemMenu(doc,kind){if(!requireUser())return;state.menuTarget={doc,kind};$('item-title').textContent=doc.title||doc.name;$('item-dialog').showModal();}
document.querySelectorAll('#item-dialog [data-action]').forEach(b=>b.onclick=async()=>{$('item-dialog').close();const {doc,kind}=state.menuTarget,action=b.dataset.action;if(action==='open'){kind==='kavita'?chooseBook(doc):kind==='blog'?importPost(doc):openSaved(doc.id);return;}if(kind==='kavita'){state.action=action;await chooseBook(doc);return;}if(kind==='blog')return importPost(doc,action);await runAction(action,doc);});
async function runAction(action,doc){if(action==='next'){state.queue=[doc.id,...state.queue.filter(id=>id!==doc.id)];await saveQueue();toast('“'+doc.title+'” toca a seguir.');}else if(action==='queue'){if(!state.queue.includes(doc.id))state.queue.push(doc.id);await saveQueue();toast('Adicionado à fila.');}else if(action==='playlist')pickPlaylist(doc.id);}
function pickPlaylist(docId){state.pickFor=docId;$('playlist-choices').hidden=!docId;const target=$('playlist-choices');target.replaceChildren();for(const playlist of state.playlists){const button=document.createElement('button');button.className='secondary';button.textContent=playlist.name+' · '+playlist.items.length;button.onclick=()=>addToPlaylist(playlist,docId);target.append(button);}if(!state.playlists.length)empty(target,'Ainda não tens playlists. Cria a primeira abaixo.');$('new-playlist-name').value='';$('playlist-dialog').showModal();}
async function addToPlaylist(playlist,docId){try{if(!playlist.items.includes(docId)){playlist.items.push(docId);await api('playlists/'+playlist.id,{method:'PUT',body:JSON.stringify({items:playlist.items})});}$('playlist-dialog').close();toast('Adicionado a “'+playlist.name+'”.');}catch(e){toast(e.message);}}
$('new-playlist-form').onsubmit=async event=>{event.preventDefault();const name=$('new-playlist-name').value.trim();if(!name)return;try{const playlist=await api('playlists',{method:'POST',body:JSON.stringify({name,items:state.pickFor?[state.pickFor]:[]})});state.playlists.push(playlist);$('playlist-dialog').close();toast(state.pickFor?'Playlist “'+name+'” criada com esta leitura.':'Playlist “'+name+'” criada.');state.pickFor=null;renderPlaylists();}catch(e){toast(e.message);}};
function listRow(id,index,buttons){const row=document.createElement('div');const info=docInfo(id);row.className='item'+(state.doc?.id===id?' playing':'')+(info?'':' missing');row.dataset.index=index;const handle=document.createElement('span');handle.className='item-handle';handle.textContent='⋮⋮';handle.tabIndex=0;handle.setAttribute('role','button');handle.setAttribute('aria-label','Arrastar para reordenar (ou setas do teclado)');row.append(handle);const number=document.createElement('span');number.className='item-index';number.textContent=index+1;const body=document.createElement('div');body.className='item-body';const h=document.createElement('h3');h.textContent=info?info.title:'Leitura removida da estante';const p=document.createElement('p');p.textContent=info?`${info.source} · ${info.sections} ${info.sections===1?'secção':'secções'}`:'';body.append(h,p);if(info)body.onclick=()=>openSaved(id);const group=document.createElement('div');group.className='item-buttons';for(const [label,title,handler] of buttons){const b=document.createElement('button');b.className='icon-button';b.textContent=label;b.title=b.ariaLabel=title;b.onclick=handler;group.append(b);}row.append(number,body,group);return row;}
// Drag rows by their handle (mouse or touch) to reorder; arrows on the focused handle do the same.
function sortable(container,list,onChange){let row=null;container.onpointerdown=e=>{const handle=e.target.closest('.item-handle');if(!handle)return;row=handle.closest('.item');row.classList.add('dragging');handle.setPointerCapture(e.pointerId);e.preventDefault();};container.onpointermove=e=>{if(!row)return;for(const other of container.querySelectorAll('.item')){if(other===row)continue;const rect=other.getBoundingClientRect();if(e.clientY<rect.top+rect.height/2&&other.compareDocumentPosition(row)&Node.DOCUMENT_POSITION_FOLLOWING){other.before(row);break;}if(e.clientY>rect.top+rect.height/2&&other.compareDocumentPosition(row)&Node.DOCUMENT_POSITION_PRECEDING){other.after(row);break;}}};container.onpointerup=container.onpointercancel=()=>{if(!row)return;row.classList.remove('dragging');row=null;const order=[...container.querySelectorAll('.item')].map(r=>list[Number(r.dataset.index)]);if(order.some((id,i)=>id!==list[i])){list.splice(0,list.length,...order);onChange();}};container.onkeydown=e=>{const handle=e.target.closest('.item-handle');const delta={ArrowUp:-1,ArrowDown:1}[e.key];if(!handle||!delta)return;e.preventDefault();const index=Number(handle.closest('.item').dataset.index);if(move(list,index,delta)){onChange();requestAnimationFrame(()=>container.querySelectorAll('.item-handle')[index+delta]?.focus());}};}
function move(list,index,delta){const target=index+delta;if(target<0||target>=list.length)return false;[list[index],list[target]]=[list[target],list[index]];return true;}
function renderQueue(){const target=$('queue-list');target.replaceChildren();if(!state.user)return empty(target,'Entra no Kavita para usar a fila.');if(!state.queue.length)return empty(target,'A fila está vazia. Usa o menu ⋯ de qualquer leitura para a adicionar.');state.queue.forEach((id,index)=>target.append(listRow(id,index,[['×','Tirar da fila',()=>{state.queue.splice(index,1);saveQueue();}]])));sortable(target,state.queue,saveQueue);updateUpNext();}
$('play-queue').onclick=()=>playNextInQueue(true);$('clear-queue').onclick=()=>{if(state.queue.length&&confirm('Limpar a fila?')){state.queue=[];saveQueue();}};$('save-queue').onclick=()=>{if(!state.queue.length)return toast('A fila está vazia.');const name=prompt('Nome da playlist:');if(!name?.trim())return;api('playlists',{method:'POST',body:JSON.stringify({name:name.trim(),items:state.queue})}).then(p=>{state.playlists.push(p);toast('Playlist “'+p.name+'” guardada.');}).catch(e=>toast(e.message));};
function updateUpNext(){const id=state.queue.find(x=>docInfo(x));const info=id&&docInfo(id);$('up-next').hidden=$('skip-next').hidden=!info;if(info)$('up-next').textContent='A seguir: '+info.title;}
$('up-next').onclick=()=>changeView('queue');$('skip-next').onclick=()=>playNextInQueue(true);
async function playNextInQueue(manual=false){const id=state.queue.find(x=>docInfo(x));if(!id){if(manual)toast('A fila está vazia.');return false;}state.queue=state.queue.filter(x=>x!==id);await saveQueue();try{await openSaved(id);seek(locate(state.position).index,locate(state.position).offset);return true;}catch(e){toast(e.message);return false;}}
function renderPlaylists(){const grid=$('playlist-grid');grid.replaceChildren();$('playlist-detail').hidden=!state.playlist;grid.hidden=Boolean(state.playlist);$('new-playlist').hidden=Boolean(state.playlist);if(state.playlist){const playlist=state.playlists.find(p=>p.id===state.playlist);if(!playlist){state.playlist=null;return renderPlaylists();}$('playlist-name').textContent=playlist.name;const target=$('playlist-items');target.replaceChildren();if(!playlist.items.length)empty(target,'Playlist vazia. Usa o menu ⋯ de uma leitura para a juntar aqui.');const save=()=>api('playlists/'+playlist.id,{method:'PUT',body:JSON.stringify({items:playlist.items})}).then(renderPlaylists).catch(e=>toast(e.message));playlist.items.forEach((id,index)=>target.append(listRow(id,index,[['×','Tirar da playlist',()=>{playlist.items.splice(index,1);save();}]])));sortable(target,playlist.items,save);return;}if(!state.user)return empty(grid,'Entra no Kavita para criar playlists.');if(!state.playlists.length)return empty(grid,'Ainda não tens playlists.');for(const playlist of state.playlists){const card=document.createElement('div');card.className='document-card';const button=document.createElement('button');button.className='document-open';const cover=document.createElement('div');cover.className='document-cover';const small=document.createElement('small');small.textContent='PLAYLIST';const title=document.createElement('span');title.className='cover-title';title.textContent=playlist.name;const symbol=document.createElement('span');symbol.className='cover-symbol';symbol.textContent='◎';cover.append(small,title,symbol);const body=document.createElement('div');body.className='document-body';const p=document.createElement('p');p.textContent=playlist.items.length+(playlist.items.length===1?' leitura':' leituras')+' · Abrir →';body.append(p);button.append(cover,body);button.onclick=()=>{state.playlist=playlist.id;renderPlaylists();};card.append(button);grid.append(card);}}
