$('rename-playlist').onclick=async()=>{const playlist=state.playlists.find(p=>p.id===state.playlist);const name=prompt('Novo nome:',playlist.name);if(!name?.trim())return;try{Object.assign(playlist,await api('playlists/'+playlist.id,{method:'PUT',body:JSON.stringify({name:name.trim()})}));renderPlaylists();}catch(e){toast(e.message);}};
