function duration(seconds){seconds=Math.max(0,Math.round(seconds));if(seconds<60)return seconds+' s';const h=Math.floor(seconds/3600),m=Math.round(seconds%3600/60);return h?`${h} h ${String(m).padStart(2,'0')} min`:`${m} min`;}
function jobSpeed(voice){return state.speeds[voice]||(voice.startsWith('sopro_')?10:voice==='kokoro_eu_pt'?20:voice==='pt_PT-tugao'||voice.startsWith('phoonnx_')?100:50);}
function docChars(){return state.doc.sections.reduce((sum,s)=>sum+chunks(s.text).reduce((n,c)=>n+c.length,0),0);}
function updateEstimate(){if(!state.doc)return;const chars=docChars();const voice=$('job-voice').value;const seconds=chars/jobSpeed(voice);const measured=Boolean(state.speeds[voice]);$('job-estimate').textContent=`${chars.toLocaleString('pt-PT')} caracteres · cerca de ${duration(seconds)} a gerar`+(measured?' (ritmo medido neste servidor)':' (estimativa; afina-se com o primeiro áudio)')+` · áudio de ~${duration(chars/14)}`;}
$('make-audio').onclick=async()=>{if(!requireUser()||!state.doc)return;try{const data=await api('jobs');state.speeds=data.speeds;state.cloud=data.cloud;}catch{}$('job-voice').replaceChildren(...[...$('voice').querySelectorAll('optgroup')].map(g=>g.cloneNode(true)));$('job-voice').value=$('voice').value;$('job-speed').value=['0.75','1','1.25','1.5'].includes($('speed').value)?$('speed').value:'1';$('job-destination').querySelector('[value=cloud]').disabled=!state.cloud;if(!state.cloud)$('job-destination').value='download';$('job-title').textContent=state.doc.title;$('job-error').textContent='';$('job-when').value='now';$('job-custom-label').hidden=true;const night=new Date();if(night.getHours()>=2)night.setDate(night.getDate()+1);night.setHours(2,0,0,0);$('job-start').value=new Date(night.getTime()-night.getTimezoneOffset()*60000).toISOString().slice(0,16);updateEstimate();$('job-dialog').showModal();};
$('job-voice').onchange=updateEstimate;$('job-when').onchange=()=>{$('job-custom-label').hidden=$('job-when').value!=='custom';};
$('job-form').onsubmit=async event=>{event.preventDefault();$('job-error').textContent='';const when=$('job-when').value;let startAt=null;if(when==='night'){const night=new Date();if(night.getHours()>=2)night.setDate(night.getDate()+1);night.setHours(2,0,0,0);startAt=night.toISOString();}else if(when==='custom'){if(!$('job-start').value)return $('job-error').textContent='Escolhe a data e a hora.';startAt=new Date($('job-start').value).toISOString();}try{await api('jobs',{method:'POST',body:JSON.stringify({doc:state.doc.id,voice:$('job-voice').value,rate:Number($('job-speed').value),destination:$('job-destination').value,startAt})});$('job-dialog').close();toast(startAt?'Áudio agendado. Vê a fila em Áudios.':'Áudio na fila. Vê o progresso em Áudios.');changeView('audio');}catch(e){$('job-error').textContent=e.message;}};
async function refreshJobs(){clearTimeout(state.jobTimer);if(!state.user){state.jobs=[];renderJobs();return;}try{const data=await api('jobs');state.jobs=data.jobs;state.speeds=data.speeds;state.cloud=data.cloud;renderJobs();}catch(e){toast(e.message);}if(!$('audio-view').hidden&&state.jobs.some(j=>['queued','running'].includes(j.status)))state.jobTimer=setTimeout(refreshJobs,6000);}
function renderJobs(){const target=$('job-list');target.replaceChildren();if(!state.jobs.length)return empty(target,state.user?'Ainda não há áudios na fila. Abre uma leitura e escolhe "Gerar áudio completo".':'Entra no Kavita para ver a tua fila de áudios.');for(const job of state.jobs){const card=document.createElement('article');card.className='job job-'+job.status;const ratio=job.total.chars?job.done.chars/job.total.chars:0;const head=document.createElement('div');head.className='job-head';const title=document.createElement('h3');title.textContent=job.title;const status=document.createElement('span');status.className='job-status';status.textContent=({queued:Date.parse(job.startAt)>Date.now()?'Agendado para '+new Date(job.startAt).toLocaleString('pt-PT',{dateStyle:'short',timeStyle:'short'}):'Na fila',running:'A gerar · '+Math.round(ratio*100)+'% · falta cerca de '+duration(job.eta),done:'Pronto · '+duration(job.seconds||0)+' de áudio',error:'Falhou',cancelled:'Cancelado'})[job.status];head.append(title,status);const meta=document.createElement('p');meta.className='job-meta';meta.textContent=[job.voiceName,job.rate+'×',job.destination==='cloud'?'pasta cloud4tb':'transferir',job.status==='queued'?'cerca de '+duration(job.eta)+' a gerar':'',job.cloudPath?'guardado em '+job.cloudPath:'',job.error||''].filter(Boolean).join(' · ');const bar=document.createElement('div');bar.className='job-bar';const fill=document.createElement('span');fill.style.width=Math.round((job.status==='done'?1:ratio)*100)+'%';bar.append(fill);const actions=document.createElement('div');actions.className='job-actions';if(job.status==='done'){const link=document.createElement('a');link.className='primary';link.href='./api/jobs/'+job.id+'/audio';link.textContent='↓ Transferir '+(job.file?.endsWith('.mp3')?'MP3':'WAV');actions.append(link);}const remove=document.createElement('button');remove.className='secondary';remove.textContent=job.status==='running'?'Cancelar':'Remover';remove.onclick=async()=>{if(job.status==='running'&&!confirm('Cancelar a geração deste áudio?'))return;try{await api('jobs/'+job.id,{method:'DELETE'});await refreshJobs();}catch(e){toast(e.message);}};actions.append(remove);card.append(head,meta,bar,actions);target.append(card);}}
$('download-audio').onclick=()=>{if(!state.blob)return toast('Ouve uma passagem primeiro para guardar o seu áudio.');const link=document.createElement('a');link.href=state.url;link.download='lectoria-'+(state.section+1)+'-'+(state.index+1)+'.wav';link.click();};
if('mediaSession'in navigator){for(const[action,handler]of Object.entries({play:()=>$('play').click(),pause:()=>{audio.pause();setStatus('paused');},seekbackward:()=>skip(-10),seekforward:()=>skip(10),previoustrack:()=>seek(Math.max(0,state.index-1)),nexttrack:()=>seek(Math.min(state.chunks.length-1,state.index+1))})){try{navigator.mediaSession.setActionHandler(action,handler);}catch{}}}
window.addEventListener('pagehide',()=>{if(state.user&&state.doc){const payload=JSON.stringify({section:state.section,position:Math.floor(state.position)});fetch('./api/documents/'+state.doc.id+'/progress',{method:'PUT',headers:{'Content-Type':'application/json'},body:payload,keepalive:true}).catch(()=>{});}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
async function applyHash(){const [name,id]=location.hash.slice(1).split('/');if(name==='reader'&&/^[a-f0-9]{32}$/.test(id||'')){if(state.doc?.id===id){changeView('reader');return;}if(state.user){try{await openSaved(id);return;}catch{}}}if(['home','kavita','blogs','shelf','queue','playlists','audio','write','settings'].includes(name)&&!(name==='reader'))changeView(name);else if(name!=='reader')changeView('home');}
window.addEventListener('popstate',()=>applyHash());
async function start(){renderDocuments();try{state.user=await api('session');updateAccount();await Promise.all([refreshShelf(),loadVoices(),loadLists()]);updateUpNext();}catch{updateAccount();}await applyHash();}
start();
